/**
 * 负责通过原婚礼 authority 顺序收集鬼魂新娘的新郎／见证人选择。
 * 输入为只读板子政策、当前阵容和引擎请求；输出为设置事实或中断结果，回合由原 owner 关闭。
 * 此协调器不改规则或绕过身份、失败及期限校验，每次请求保留原 factory 和 opaque turn。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { GHOST_BRIDE_POLICY, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  Phase,
  type World,
  type GameEvent,
  type ActionProvider,
  type ActionStage,
  type ToolName,
} from "../../../../core/domain";
import { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  beginWeddingSetup,
  openWeddingTurn,
  closeWeddingTurn,
  closeWeddingSetup,
  ghostBrideReady,
  weddingSetup,
  weddingPair,
  weddingGroup,
  weddingActorView,
  weddingNightCapture,
  authorizedWeddingTurn,
  commitWeddingTool,
  takeWeddingChat,
} from "./authority";
/** 每次调用使用真实引擎工厂及 opaque 原回合，不启用 fallback。 */
export async function executeWeddingTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  actorId: number;
  kind: "bridegroom" | "chat" | "witness" | "knife";
  tool: ToolName;
  stage: ActionStage;
  isCurrent: () => boolean;
}): Promise<void> {
  const { world, gateway, events, provider, day, actorId, kind, tool, stage, isCurrent } = input;
  const scope = openWeddingTurn(world, kind, actorId, day, isCurrent);
  try {
    const view = weddingActorView(world, actorId);
    const request = new GameActionRequestFactory(world, events, day).create({
      phase: Phase.Night,
      actorId,
      allowedTools: [tool],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.night_action" },
      context: {
        allow_fallback: false,
        action_failure_policy: "error",
        ...(kind === "witness" && view && "proposedWitnessId" in view
          ? { proposedWitnessId: view.proposedWitnessId }
          : {}),
      },
    });
    const raw = await provider.getAction(request);
    if (!authorizedWeddingTurn(world, actorId, Phase.Night, day, scope))
      throw new Error("ghost_bride_turn_revoked");
    const call = readWeddingTool(raw);
    if (!call || call.name !== tool) throw new Error("ghost_bride_required_action_missing");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Night,
      day,
      ghostBrideScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw new Error("ghost_bride_action_invalid");
    const committed = commitWeddingTool(scope, call);
    const pair = weddingPair(world);
    if (!pair) throw new Error("ghost_bride_pair_unavailable");
    if (kind === "bridegroom" && committed)
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_pair_chosen",
        payload: { ...pair },
        audience: Object.freeze([pair.brideId, pair.groomId].sort((a, b) => a - b)),
      });
    if (kind === "witness" && call.name === "choose_wedding_witness") {
      const votes = weddingSetup(world)!.witnessVotes;
      if (votes.some((v) => v.actorId === actorId && v.targetId === call.args.target_id))
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_witness_vote",
          payload: {
            policy: GHOST_BRIDE_POLICY,
            groupId: pair.groupId,
            day: 1,
            actorId,
            targetId: call.args.target_id,
            voteIndex: votes.length as 1 | 2,
          },
          audience: Object.freeze([]),
        });
      const group = weddingGroup(world);
      if (committed && group)
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_group_chosen",
          payload: { ...group },
          audience: Object.freeze(
            [group.brideId, group.groomId, group.witnessId].sort((a, b) => a - b),
          ),
        });
    }
    if (
      kind === "knife" &&
      committed &&
      (call.name === "kill_vote" || call.name === "wedding_kill_vote")
    ) {
      const capture = weddingNightCapture(world, day)!;
      if (capture.owner === "none") throw new Error("ghost_bride_knife_owner_invalid");
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_knife_vote",
        payload: {
          policy: GHOST_BRIDE_POLICY,
          groupId: pair.groupId,
          day,
          owner: capture.owner,
          actorId,
          targetId: call.args.target_id,
          abstain: call.args.abstain,
        },
        audience: Object.freeze(capture.owner === "ordinary_pack" ? [] : [actorId]),
      });
      if (capture.owner === "ordinary_pack")
        events.push({
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: { actorId, targetId: call.args.target_id, abstain: call.args.abstain },
          audience: Object.freeze([...capture.actorIds].sort((a, b) => a - b)),
        });
    }
    const actualDisagreement =
      kind === "witness" &&
      call.name === "choose_wedding_witness" &&
      weddingSetup(world)!.witnessVotes.some(
        (v) => v.actorId === actorId && v.targetId === call.args.target_id,
      );
    const recordCommit = () =>
      safeRecordLogicOp({
        scope: "gateway",
        op: "validate_tool_call",
        actorId,
        phase: Phase.Night,
        status: "ok",
        input: { tool: call.name, args: call.args },
      });
    if (kind !== "chat" && (committed || actualDisagreement)) recordCommit();
    if (!committed) throw new Error("ghost_bride_action_commit_failed");
    if (kind === "chat") {
      const message = takeWeddingChat(scope);
      if (!message) throw new Error("ghost_bride_chat_delivery_revoked");
      recordCommit();
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_partner_chat",
        payload: { policy: GHOST_BRIDE_POLICY, groupId: pair.groupId, ...message },
        audience: Object.freeze([message.actorId, message.recipientId].sort((a, b) => a - b)),
      });
    }
  } finally {
    closeWeddingTurn(scope);
  }
}
export class GhostBrideSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (ghostBrideReady(this.world)) return true;
    const setup = weddingSetup(this.world);
    if (!setup || setup.status !== "pending" || day !== 1)
      throw new Error("ghost_bride_setup_unavailable");
    try {
      beginWeddingSetup(this.world, config, isCurrent);
      const base = {
        world: this.world,
        gateway: this.gateway,
        events: this.events,
        provider,
        day,
        isCurrent,
      };
      await executeWeddingTurn({
        ...base,
        actorId: setup.actorId,
        kind: "bridegroom",
        tool: "choose_bridegroom",
        stage: "ghost_bride_groom",
      });
      const pair = weddingPair(this.world)!;
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "chat",
          tool: "speak_to_partner",
          stage: "ghost_bride_chat",
        });
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "witness",
          tool: "choose_wedding_witness",
          stage: "ghost_bride_witness",
        });
      if (!isCurrent() || !ghostBrideReady(this.world))
        throw new Error("ghost_bride_setup_revoked");
      return true;
    } finally {
      closeWeddingSetup(this.world, isCurrent() ? "failed" : "cancelled");
    }
  }
}

/**
 * 负责鬼魂新娘伴侣聊天及婚约狼刀请求。输入为绑定婚约夜、原参与者和已验证选择；输出为聊天结算、刀口与事实。
 * 婚约权威拥有原付款、投票和关闭；本阶段保 await 后真实复验，不令旧 pending 请求重新有效。
 * priority=150／400 的原顺序保持，过期普通／婚约狼刀清理归规则组合，历史票不重建或退款。
 */
import { StatusMark, COMPONENT } from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import type { NightStageHandler } from "../../stages/night/contracts";
import { executeWeddingTurn } from "./setup";
import {
  weddingPair,
  weddingNightCapture,
  resolveWeddingKnife,
  weddingKnifeCurrent,
} from "./authority";
export const WEDDING_CHAT_STAGE: NightStageHandler = {
  id: "ghost_bride_chat",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay(),
      pair = weddingPair(ctx.world);
    if (
      day === 1 ||
      !pair ||
      ![pair.brideId, pair.groomId].every(
        (id) => ctx.world.getComponent(id, COMPONENT.Alive)?.alive === true,
      )
    )
      return;
    for (const actorId of [pair.brideId, pair.groomId])
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "chat",
        tool: "speak_to_partner",
        stage: "ghost_bride_chat",
        isCurrent: ctx.isCurrent,
      });
  },
};
export const WEDDING_KNIFE_STAGE: NightStageHandler = {
  id: "ghost_bride_knife",
  priority: 400,
  async execute(ctx) {
    const day = ctx.currentDay(),
      capture = weddingNightCapture(ctx.world, day);
    if (!capture) throw new Error("ghost_bride_capture_missing");
    for (const actorId of capture.actorIds) {
      const tool = capture.owner === "ordinary_pack" ? "kill_vote" : "wedding_kill_vote";
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "knife",
        tool,
        stage: capture.owner === "ordinary_pack" ? "wolf_vote" : "ghost_bride_knife",
        isCurrent: ctx.isCurrent,
      });
      // 原投票仍由婚约权威保存，本阶段不从事实或目标重建票表。
    }
    const targetId = resolveWeddingKnife(ctx.world, day);
    ctx.events.push({
      timestamp: Date.now(),
      type: "ghost_bride_knife_resolved",
      payload: { ...capture, actorIds: [...capture.actorIds], targetId },
      audience: Object.freeze(
        capture.owner === "ordinary_pack" ? [] : [...capture.actorIds].sort((a, b) => a - b),
      ),
    });
    ctx.state.wolfTarget = targetId;
    if (targetId !== null && weddingKnifeCurrent(ctx.world, day, targetId)) {
      const marks = ctx.ensureMarks(targetId),
        life = ctx.world.getComponent(targetId, COMPONENT.Alive)!;
      marks.add(StatusMark.WolfKillMark);
      ctx.state.wolfTargetScope = { targetId, life, version: aliveLifeVersion(life)!, marks };
    }
  },
};

/**
 * 负责女巫每夜标记复位和原捕获瓶数/目标的用药选择。
 * 输入为当前 native/granted potion 与已验证行动；输出保留已付救/毒、跳过和历史。
 * 原毒 intent 从原 source/target/day 及原请求读取点捕获的 abilityId 生成，不增加时钟/World/RNG读取。
 * 付款、目标映射、第二次行动、角色专有失败和 poison-only 限制保持原位置。
 * 来源句柄只供运行时消费，不进入玩家信息或 schema2；瓶数／旗标归 Witch 状态 owner，公共次数归实例 owner。
 */
import { WITCH_STATE_SLOT } from "./ports";
/** 文件说明：女巫夜间用药阶段处理。 */
import {
  captureNightLife,
  livingNightLife,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import {
  Phase,
  PotionType,
  Role,
  StatusMark,
  WitchSelfHealRule,
} from "../../../../core/domain/model";
import { type NightAbilityReadView } from "../abilities";
import { nativePotionsCanCombine, witchKnifeVisible } from "./policies";
import { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import {
  getWitchState,
} from "./ports";
import { activeNightAbility, allNightAbilities } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";
import { captureNightAbilityScope } from "../ability_scope";

const resetNightRoleStateStage: NightStageHandler = {
  id: "reset_night_role_state",
  priority: 100,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) return;
    for (const id of ctx.world.getAliveEntityIds()) {
      const role = ctx.world.getComponent(id, COMPONENT.Role);
      for (const ability of allNightAbilities(role)) {
        if (ability.kind !== "potion") continue;
        const witchState = ability.state;
        WITCH_STATE_SLOT.allowedWrites.resetWitchNightState(witchState, () => ctx.currentDay());
      }
    }
  },
};

const witchActionStage: NightStageHandler = {
  id: "witch_action",
  priority: 500,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      if (!ctx.nativeNightFailure.requiresDemonPotionTurn()) return;
      const { executeDemonWitchTurn } = await ctx.nativeNightEffects.loadSealedPotionController();
      const result = await executeDemonWitchTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day: ctx.currentDay(),
        wolfTarget: ctx.state.wolfTarget,
      });
      if (result.poison) (ctx.state.poisonClaims ??= []).push(result.poison.claim);
      return;
    }
    for (const { actorId: witchId, ability } of ctx.nightActors.actors(
      "potion",
      ctx.currentDay(),
    )) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      if (ctx.nativeNightFailure.skipsEmptyBorrowedPotion(ability)) continue;
      const day = ctx.currentDay();
      const ownership = captureNightAbilityScope(
        ctx.world,
        witchId,
        ability,
        day,
        () => ctx.isCurrent() && ctx.currentDay() === day,
      );
      if (!ownership?.isEligible()) continue;
      const close = () => {
        if (ownership.isOwnerCurrent() && !ability.disabled && !ability.deathExpired)
          WITCH_STATE_SLOT.allowedWrites.closeWitchPotionTurn(ability, day);
      };
      const both = nativePotionsCanCombine(ability);
      for (let turn = 0; turn < (both ? 2 : 1); turn++) {
        if (
          !activeNightAbility(
            ctx.world.getComponent(witchId, COMPONENT.Role),
            "potion",
            ctx.currentDay(),
            ability.id,
          )
        )
          break;
        const used = await executePotionTurn(ctx, witchId, ability);
        if (!ctx.isCurrent()) return;
        if (!used) {
          if (both) close();
          break;
        }
      }
      if (both) close();
    }
  },
};

/** 女巫夜间阶段列表。 */
export const WITCH_NIGHT_STAGES: NightStageHandler[] = [resetNightRoleStateStage, witchActionStage];

async function executePotionTurn(
  ctx: NightStageContext,
  witchId: number,
  ability: NightAbilityReadView<"potion">,
): Promise<boolean> {
  ctx.nativeNightFailure.assertNativeActor(witchId, Role.Witch);
  ctx.nativeNightFailure.assertPotionSource(ability);
  const day = ctx.currentDay();
  const scope = captureNightAbilityScope(
    ctx.world,
    witchId,
    ability,
    day,
    () => ctx.isCurrent() && ctx.currentDay() === day,
  );
  if (!scope?.isEligible()) return false;
  WITCH_STATE_SLOT.allowedWrites.refreshWitchSelfHeal(ability, day);
  const targets = new Map(
    ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
  );
  const attribution = ability.source.kind === "native" ? {} : { abilityId: ability.id };
  let effectAbilityId: string;
  const req = ctx.makeRequest(witchId, ["use_potion"], {
    stage: "witch",
    ...ctx.nativeNightTargets.potionModifierHints(witchId),
    ability_id: (effectAbilityId = ability.id),
    ...(witchKnifeVisible(ability)
      ? {
          wolf_target: ctx.state.wolfTarget,
          ...ctx.nativeNightTargets.potionKnifeHints(),
        }
      : {}),
  });
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  const action = await ctx.actionProvider.getAction(req);
  if (!ctx.isCurrent()) return false;
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  if (action?.name !== "use_potion") {
    ctx.nativeNightFailure.actionMissing("witch");
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: {
        actorId: witchId,
        ...attribution,
        targetId: null,
        potionType: PotionType.None,
        reason: "no_action",
      },
    });
    return false;
  }

  const result = ctx.toolGateway.validateAndSanitize(ctx.world, witchId, action, {
    phase: Phase.Night,
    day: ctx.currentDay(),
    abilityId: ability.id,
  });
  if (!ctx.isCurrent()) return false;
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  if (!result.ok || !result.sanitizedCall) {
    ctx.nativeNightFailure.actionInvalid("witch");
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: {
        actorId: witchId,
        ...attribution,
        targetId: action.args.target_id ?? null,
        potionType: PotionType.None,
        reason: "invalid_action",
      },
    });
    return false;
  }

  const witch = ctx.world.getComponent(witchId, COMPONENT.Role);
  if (!activeNightAbility(witch, "potion", ctx.currentDay(), ability.id)) return false;
  const witchState = witch ? getWitchState(witch, ability.id) : undefined;
  if (!witchState) {
    return false;
  }
  const targetId = result.sanitizedCall.args.target_id;
  const potion = result.sanitizedCall.args.potion_type;
  const requestedTarget = targets.get(targetId);
  if (
    potion !== PotionType.None &&
    (!requestedTarget || !livingNightLife(ctx.world, requestedTarget))
  )
    return false;
  const mapping =
    potion !== PotionType.None
      ? ctx.nativeNightTargets.mappedTarget(
          () => day,
          () => targetId,
        )
      : null;
  if (mapping && !mapping.isCurrent()) throw new Error("magician_potion_target_stale");
  const receipt =
    potion === PotionType.Poison
      ? ctx.nativeNightTargets.reflectedTarget(
          () => day,
          () => witchId,
          () => targetId,
          "poison",
        )
      : null;
  if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Witch))
    throw new Error("time_consort_witch_source_invalid");
  const effectiveId = receipt?.effectiveId ?? mapping?.effectiveId ?? targetId;
  const target = receipt?.scope ?? mapping?.scope ?? requestedTarget;

  if (potion === "heal") {
    if (
      witchState.heal <= 0 ||
      witchState.healUsedThisNight ||
      (witchState.poisonUsedThisNight && !nativePotionsCanCombine(ability))
    )
      return false;
    recordNightAbilityUse(ability, day, true);
    ctx.ensureMarks(effectiveId).add(StatusMark.HealMark);
    WITCH_STATE_SLOT.allowedWrites.consumeWitchHeal(witchState);
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_used",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.Heal },
    });
  }

  if (potion === "poison") {
    if (
      witchState.poison <= 0 ||
      witchState.poisonUsedThisNight ||
      (witchState.healUsedThisNight && !nativePotionsCanCombine(ability))
    )
      return false;
    if (!luckyTargetAllowed(ctx.world, witchId, ability, day, "poison", targetId)) return false;
    const source = captureNightLife(ctx.world, witchId);
    if (!source || !target) return false;
    ctx.nativeNightEffects.commitReflectedTarget(receipt, day, witchId, "poison");
    recordNightAbilityUse(ability, day, true);
    (ctx.state.poisonClaims ??= []).push(
      originalPoisonIntent(
        { source, target },
        {
          family: "witch",
          day,
          stage: "witch",
          actorLife: source,
          requestedTargetId: targetId,
          abilityId: effectAbilityId,
        },
      ),
    );
    ctx.ensureMarks(effectiveId).add(StatusMark.PoisonMark);
    WITCH_STATE_SLOT.allowedWrites.consumeWitchPoison(witchState);
    ctx.nativeNightEffects.commitNativeReflection(
      "poison",
      ability,
      targetId,
      () => source,
      () => scope.isOwnerCurrent() && !ability.disabled && !ability.deathExpired,
    );
    recordOwnNightAction(ctx.world, witchId, day, "poison", targetId, false);
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_used",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.Poison },
    });
  }

  if (potion === "none") {
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.None },
    });
  }
  if (potion === PotionType.None) recordNightAbilityUse(ability, day, false);
  ctx.nativeNightEffects.recordModifierTarget(day, witchId, "poison", () =>
    potion === PotionType.Poison ? targetId : null,
  );
  return potion !== PotionType.None;
}

/**
 * 负责流水线与 handler 共享的夜间状态及执行端口契约。
 * 输入为捕获的阶段操作、已付效果和 actor 查询；输出为有类型的贡献及原状态引用。
 * 机械、觉醒和原毒的内建生产者提交 sourced intent，源原体/因果信息只供运行时消费。
 * 旧原毒／机械／觉醒注入 effect/claim 保留接受宽度；其额外 kind/origin/getter 不被当作新协议读取。
 * 所有内建原毒（含受赠及学者加成）均有来源；此契约不查询 World 或提交库存。
 * 这些外部自定义注入仍保留明确 legacy 接受政策，不把同名字段视为 owned 来源。
 * 本族加成回执、恶夜骑士绑定与摄梦关系不属于通用字段，分别按本夜状态身份由各本族唯一所有者保存。
 */
import { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import {
  ActionProvider,
  ActionRequest,
  ActionRequestExtras,
  ActionStage,
  EntityId,
  GameEvent,
  ExileFeedback,
  NightSummary,
  Role,
} from "../../../../core/domain/model";
import { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { RoleCatalog } from "../../roles/catalog";
import type { NightAbilityActorQuery } from "../../roles/night-ability-actors";
import type { AliveComponent } from "../../../../core/domain/components/alive";
import type { NativeNightFailurePolicy } from "../../../../rulesets/native-night-failure-policy";
import type { NativeNightTargetPolicy } from "../../../../rulesets/native-night-target-policy";
import type { NativeNightEffects } from "../../../../rulesets/native-night-effects";

import type {
  NightPoisonClaim,
  NightInspectionAttack,
  NightFoxInspectionClaim,
  NightMechanicalEffect,
  NightGuardClaim,
  NightMerchantBacklash,
  NightBlackMarketBacklash,
  NightAwakenedEffect,
  NightMechanicalIntent,
  NightAwakenedIntent,
  NightOriginalPoisonIntent,
} from "../../../../core/domain/night_effects";

/** 狼刀选定时捕获的原生命及印记引用；目标序号相同不代表原体和生命版本仍有效。 */
export interface WolfKnifeTargetScope {
  targetId: EntityId;
  life: AliveComponent;
  version: number;
  marks: StatusMarksComponent;
}

/**
 * 同一夜按阶段顺序累积的运行状态，流水线创建，具体 handler 写入所属效果。
 * 包含原组件、回执和当前性查询，不能直接序列化为玩家观察或录制格式。
 * 效果条目是运行提案或捕获记录；空容器存在不表示已付、有效或已标死，这些由各所有者分别核对。
 */
export interface NightStageState {
  /** 学者／导师在原冲突检查点产生的死亡与刀口；不是直接修改 Alive 的指令。 */
  modifierDeaths?: import("../../../../core/domain/night_effects").NightLifeScope[];
  modifierKnifeTargets?: EntityId[];
  wolfChatOrder: EntityId[];
  endedWolves: Set<EntityId>;
  wolfVotes: Record<number, number>;
  wolfTarget: EntityId | null;
  wolfTargetScope?: WolfKnifeTargetScope;
  /** 实际参与选定普通狼刀的投票者；票表的目标键不能代替投票者名单。 */
  wolfTargetVoters?: EntityId[];
  seerChecks: NightSummary["seerChecks"];
  /** 内建有来源 intent 与旧注入 claim 共存；仅同名字段不能把旧对象变成内建来源。 */
  poisonClaims?: Array<NightOriginalPoisonIntent | NightPoisonClaim>;
  inspectionAttacks?: NightInspectionAttack[];
  retaliationAttacks?: import("../../../../core/domain/night_effects").NightRetaliationAttack[];
  nightImmunities?: import("../../../../core/domain/night_effects").NightImmunityClaim[];
  foxInspections?: NightFoxInspectionClaim[];
  guardClaims?: NightGuardClaim[];
  merchantBacklashes?: NightMerchantBacklash[];
  blackMarketBacklashes?: NightBlackMarketBacklash[];
  /** 机械效果按护盾、攻击、失败分别保留，消费次数和来源规则由具体能力控制。 */
  mechanicalEffects?: {
    shields: Array<NightMechanicalIntent<"mechanical-shield"> | NightMechanicalEffect>;
    attacks: Array<NightMechanicalIntent<"mechanical-attack"> | NightMechanicalEffect>;
    failures: Array<NightMechanicalIntent<"mechanical-failure"> | NightMechanicalEffect>;
  };
  /** 觉醒效果与机械效果分列，不能因形状相近而合并付款或退休政策。 */
  awakenedEffects?: {
    shields: Array<NightAwakenedIntent<"awakened-shield"> | NightAwakenedEffect>;
    attacks: Array<NightAwakenedIntent<"awakened-attack"> | NightAwakenedEffect>;
  };
}

/**
 * 阶段 handler 使用的运行端口：请求、候选查询和效果写入均在当前阶段执行。
 * 异步行动返回后仍需检查 isCurrent 及具体原体许可；持有此上下文不自动获得领域提交权限。
 */
export interface NightStageContext {
  isCurrent(): boolean;
  readonly previousExile: Readonly<ExileFeedback> | null;
  world: World;
  roleCatalog: RoleCatalog;
  readonly nightActors: NightAbilityActorQuery;
  readonly nativeNightFailure: NativeNightFailurePolicy;
  readonly nativeNightTargets: NativeNightTargetPolicy;
  readonly nativeNightEffects: NativeNightEffects;
  toolGateway: ToolGateway;
  events: GameEvent[];
  actionProvider: ActionProvider;
  currentDay(): number;
  makeRequest(
    actorId: EntityId,
    allowedTools: ActionRequest["allowedTools"],
    context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
  ): ActionRequest;
  getAliveByRole(role: Role): EntityId[];
  ensureMarks(entityId: EntityId): StatusMarksComponent;
  pickMajorityTarget(votes: Record<number, number>): EntityId | null;
  /** 迷雾有限板在所有投票者明确放弃后使用的回退，随机流具名且可复现。 */
  pickMistKnife?(ids: readonly EntityId[]): EntityId | null;
  shuffleWolves(ids: EntityId[]): EntityId[];
  state: NightStageState;
}

/** 默认收集器按原 priority 装配，流水线按计划原顺序执行；处理器返回不等于效果已造成实际死亡。 */
export interface NightStageHandler {
  id: string;
  priority: number;
  execute(ctx: NightStageContext): Promise<void>;
}

/**
 * 负责：顺序执行夜间阶段、收集有来源的效果并准备黎明伤害。
 * 输入：当前 World、真实 RulePlan、阶段贡献和行动提供者；输出：原夜间摘要与死亡提案。
 * 原生策略和具体生命周期单位由同一计划装配；actor、目标、库存和原体资格仍现场查询。
 * 默认阶段固定成员及顺序，注入惰性来源在前一阶段提交后才拉取下一项。
 * 取消检查后，参数仍在首次 acquired 的原 World 参数位置绑定；改变参数不隐式重编译。
 * 来源元数据不授予资格；原 handler receiver 与 execute getter 保持晚读取。
 * 已捕获 day 原值交给伤害折叠，机械／觉醒／原毒 intent 单独保留来源及原体；
 * intent 元数据不进入夜间摘要、事件或 schema2，旧注入 claim 保持兼容。
 * 晚交接保留真实单位的 owned 状态和原失败前缀，result 与最终伤害仍在原已付效果之后准备。
 * 已提交重入准入交有限规则组合，在原婚约开夜之后检查；拒绝不撤销原已付效果，原 finally 仍收尾。
 * 明辉／梦及增益伤害与猎魔来源交付各归具名规则组合；本流水线保封存、伤害结算及死亡生命捕获的原检查点。
 * 运行梦句柄、猎魔 token 与晚保护闭包不进入玩家摘要或归档。
 */
import { attachNightUnit } from "../../../core/domain/night-unit";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { prepareNightPipelineLifecycle, type NightLifecycleHandoff } from "../../../rulesets/night-lifecycle-plan";


import { assertNightSetupReady, assertNightReadable } from "../../../rulesets/night-readability";
import { RulePlan } from "../../../rulesets/rule-plan";
import { bindNightAbilityActorQuery } from "../../mechanisms/roles/night-ability-actors";
import { isFragrantPairBoard, fragrantAuthoritySnapshot } from "../../mechanisms/roles/fragrant_pair_seer/ports";
import { createNobleNightAbortReceiver, attachNobleNightReceiver, checkpointNobleBodyAuthority, isNobleBodyBoard } from "../../mechanisms/roles/noble_secret_body/ports";
import { animalAuthoritySnapshot } from "../../mechanisms/roles/animal_dream/ports";
import { isRadiantEclipseBoard } from "../../mechanisms/roles/radiant_eclipse/ports";
